/// Explanations.
pub(super) const HELP: &[(&str, &str)] = &[
    ("dns_statistics.answered", "## Respondido por\nQuem respondeu cada consulta: o cache, um servidor de cima, uma resposta vencida (RFC 8767), uma entrada estática, a adlist ou uma zona, ou recusada (fora do Allowed From, acima do limite por cliente ou de consultas simultâneas, malformada)."),
    ("dns_statistics.answers_per_sec", "## Respostas/s\nRespostas desse servidor por segundo no último minuto."),
    ("dns_statistics.by_cache", "## Cache\nRespondidas do cache, sem perguntar a ninguém."),
    ("dns_statistics.by_refused", "## Recusado / Limite\nNão respondidas de verdade: cliente fora do Allowed From (REFUSED), acima do `max-queries-per-client` (descartada em UDP, REFUSED em TCP), acima do `max-concurrent-queries` (SERVFAIL) ou malformada."),
    ("dns_statistics.by_stale", "## Vencido\nNenhum servidor respondeu e o cache tinha uma resposta vencida ainda dentro da janela de serve-stale: ela foi servida com TTL de 30 s (RFC 8767)."),
    ("dns_statistics.by_static", "## Estático / Adlist\nRespondidas pelo próprio roteador: entradas estáticas (`/ip dns static`), bloqueios da adlist, zonas autoritativas e nomes especiais (RFC 6761)."),
    ("dns_statistics.by_upstream", "## Servidor\nPerguntadas a um servidor de cima (a resposta entrou no cache)."),
    ("dns_statistics.cache_entries", "## Entradas\nRespostas guardadas agora (positivas e negativas, de qualquer tipo)."),
    ("dns_statistics.cache_hits", "## Acertos do cache\nDas consultas que precisaram do resolvedor (cache, servidor ou vencida), quantas o cache respondeu, na média do período (não desde o reset).\n\nAbaixo de ~50 % numa LAN comum, o `cache-size` pode estar pequeno (veja Despejos na aba Cache) ou há muitos nomes únicos."),
    ("dns_statistics.cache_used", "## Usado / Máximo\nA memória estimada das entradas contra o `cache-size` (IP › DNS)."),
    ("dns_statistics.client", "## Cliente\nO endereço que fez as consultas; um cliente IPv6 é o /56 dele."),
    ("dns_statistics.client_limited", "## Limitadas\nConsultas desse cliente acima do `max-queries-per-client` (descartadas em UDP, REFUSED em TCP)."),
    ("dns_statistics.client_nxdomain", "## NXDOMAIN %\nDas consultas desse cliente, quantas foram respondidas com NXDOMAIN. Alto num cliente só: malware procurando os servidores dele (DGA), um aparelho em laço, ou a origem de um ataque de subdomínio aleatório."),
    ("dns_statistics.client_queries", "## Consultas\nQuantas consultas desse cliente desde o reset."),
    ("dns_statistics.client_rate", "## Consultas/s\nAs consultas desse cliente por segundo nos últimos 10 s."),
    ("dns_statistics.client_refused", "## Recusadas\nConsultas desse cliente recusadas (fora do Allowed From) ou descartadas pelo limite por cliente."),
    ("dns_statistics.client_seen", "## Visto há\nHá quanto tempo esse cliente perguntou pela última vez. Fica cinza depois de um minuto e continua na tabela até um cliente mais ativo tomar o lugar."),
    ("dns_statistics.client_share", "## %\nA fração das consultas totais que veio desse cliente."),
    ("dns_statistics.clients", "## Clientes\nOs endereços que mais perguntaram desde o reset, ao vivo: um cliente IPv6 é o /56 dele (o que se delega a uma casa, não cada endereço temporário dos aparelhos). A memória é fixa: com mais clientes do que cabem, o de menor contagem dá lugar (Space-Saving); \"≤\" indica que parte da contagem pode ser de quem ele substituiu. Nada vai para o disco e nenhum nome fica guardado por cliente (LGPD)."),
    ("dns_statistics.domain", "## Domínio\nO domínio a que os nomes com falha pertencem."),
    ("dns_statistics.domain_names", "## Nomes\nQuantos nomes diferentes desse domínio falharam, estimado por HyperLogLog (±6,5 %, 256 bytes por domínio). Perto do número de falhas: quase todo nome era novo, a marca de um ataque de subdomínio aleatório."),
    ("dns_statistics.domain_nxdomain", "## NXDOMAIN\nNomes desse domínio respondidos com \"não existe\" desde o reset."),
    ("dns_statistics.domain_rate", "## Falhas/s\nNXDOMAIN e SERVFAIL desse domínio por segundo nos últimos 10 s."),
    ("dns_statistics.domain_servfail", "## SERVFAIL\nNomes desse domínio que receberam SERVFAIL desde o reset (os servidores dele não responderam, o DNSSEC falhou ou o limite de simultâneas bateu)."),
    ("dns_statistics.encrypted_in", "## DoT / DoH de entrada\nO roteador ainda não atende DNS over TLS nem DNS over HTTPS para a LAN: só os usa para perguntar aos servidores de cima (IP › DNS, `use-doh-server`)."),
    ("dns_statistics.evicted", "## Despejos\nEntradas ainda válidas jogadas fora para caber uma nova, desde o reset. Se cresce sempre, o `cache-size` é pequeno para a LAN, ou um ataque de nomes únicos está empurrando os nomes quentes para fora (veja G4.1x)."),
    ("dns_statistics.expired", "## Expiradas\nEntradas removidas depois do TTL e da janela de serve-stale."),
    ("dns_statistics.failing_domains", "## Domínios com falha\nOs domínios cujos nomes receberam NXDOMAIN ou SERVFAIL desde o reset. Um nome conta no domínio dele: os dois últimos rótulos, ou três sob um código de país com segundo nível genérico (`vitima.com.br`, `bbc.co.uk`); nomes reversos por /16 (IPv4) ou /32 (IPv6). \"nomes aleatórios\" marca um domínio falhando rápido em muitos nomes diferentes: um ataque de subdomínio aleatório (water torture) contra os servidores dele, ou um cliente quebrado."),
    ("dns_statistics.in_flight", "## Em voo\nConsultas esperando um servidor de cima agora, contra o `max-concurrent-queries`. Ao bater no limite, a consulta seguinte recebe SERVFAIL na hora (o cliente tenta o outro DNS dele). Embaixo, o máximo desde o reset e quantas vezes o limite foi atingido."),
    ("dns_statistics.latency", "## Latência p50 / p99\nO tempo entre ler a consulta e enviar a resposta ao cliente, no último minuto: a mediana (p50, metade é mais rápida) e o percentil 99 (só 1 % é mais lenta). Sem leituras no minuto, desde o reset.\n\nDo cache sai em microssegundos; o p99 alto mostra os servidores de cima lentos ou os timeouts."),
    ("dns_statistics.malformed", "## Malformadas\nMensagens recusadas antes da cadeia: menores que um cabeçalho, ilegíveis (FORMERR), outro opcode (NOTIMP), outra classe ou AXFR fora do lugar. Muitas indicam varredura ou um cliente quebrado."),
    ("dns_statistics.name", "## Nome\nO nome perguntado, em minúsculas."),
    ("dns_statistics.name_queries", "## Consultas\nQuantas vezes o nome foi perguntado desde o reset."),
    ("dns_statistics.name_rate", "## Consultas/s\nConsultas por esse nome por segundo nos últimos 10 s."),
    ("dns_statistics.name_share", "## %\nA fração das consultas totais que perguntou esse nome."),
    ("dns_statistics.names", "## Nomes mais perguntados\nOs nomes mais perguntados desde o reset, de todos os clientes juntos (como o `top-queries` do PowerDNS ou o `stats.frequent` do Knot). A memória é fixa: com mais nomes do que cabem, o de menor contagem dá lugar (Space-Saving); \"≤\" indica que parte da contagem pode ser de nomes que ele substituiu. Uma enxurrada de nomes aleatórios nunca tira da lista um nome muito perguntado."),
    ("dns_statistics.period", "## Período\nA janela do gráfico e dos cartões que leem dele (pico de consultas, acertos do cache, SERVFAIL): última hora (pontos de 1 s), últimas 24 h (1 min) ou últimos 7 dias (5 min). A história vem do Graphing (System › Graphing), série `dns`."),
    ("dns_statistics.queries_per_sec", "## Consultas por segundo\nO número grande é a média dos últimos 10 s. Embaixo, o maior valor do período escolhido e a hora (UTC) em que aconteceu.\n\nUm pico fora do normal sem cliente novo pode ser ataque de nomes aleatórios ou um dispositivo em laço."),
    ("dns_statistics.rcodes", "## Códigos de resposta\nO RCODE de cada resposta (RFC 1035 §4.1.1): NOERROR, NXDOMAIN (o nome não existe), SERVFAIL (falha), REFUSED, FORMERR (consulta malformada), NOTIMP (operação não suportada). Dropped: sem resposta (limite em UDP ou lixo)."),
    ("dns_statistics.reset", "## Zerar estatísticas\nVolta os contadores a zero (`ip.dns.statistics.reset`). Não mexe na configuração nem no cache e não entra no rollback: é só contagem. O histórico do gráfico continua."),
    ("dns_statistics.rtt_histogram", "## Tempo de ida e volta por faixa\nQuantas respostas caíram em cada faixa: abaixo de 1 ms, 1–10, 10–100, 100–500, 500–1600 e acima de 1600 ms, desde o reset. As pontas sempre aparecem: a faixa acima de 1600 ms mostra os quase-timeouts. Com uma linha selecionada na tabela, só aquele servidor."),
    ("dns_statistics.rtt_p50", "## p50 ms\nO tempo de ida e volta mediano das respostas dele, em ms, no último minuto (sem respostas no minuto, desde o reset). Calculado pelas faixas do histograma: a largura da faixa é o erro."),
    ("dns_statistics.rtt_p95", "## p95 ms\nO percentil 95 do tempo de ida e volta: só 5 % das respostas demoraram mais. Acima de 500 ms o servidor fica `slow`."),
    ("dns_statistics.server", "## Servidor\nO endereço do servidor de cima."),
    ("dns_statistics.servfail", "## SERVFAIL\nA fração das respostas com SERVFAIL na média do período. Embaixo, o erro estendido (EDE, RFC 8914) mais comum: 22 \"No Reachable Authority\" é nenhum servidor de cima respondeu; 13 \"Cached Error\" é uma falha recente ainda em espera (RFC 9520); 18 \"Prohibited\" é cliente fora do Allowed From. O roteador também envia o código aos clientes que usam EDNS (opção 15): o `dig` mostra como \"EDE\"."),
    ("dns_statistics.socket_drops", "## Descartes no socket\nConsultas que o kernel jogou fora porque a fila do socket UDP encheu antes de uma thread ler (`/proc/net/udp`, coluna drops). Qualquer número aqui é cliente sem resposta: o roteador não deu conta da rajada."),
    ("dns_statistics.stale_served", "## Vencidas servidas\nRespostas vencidas entregues porque nenhum servidor respondeu (RFC 8767): o cliente não ficou sem resposta durante a queda."),
    ("dns_statistics.state", "## Estado\n`up` responde bem; `slow` com p95 acima de 500 ms ou muitos timeouts no último minuto; `down` falhou e vai para o fim da fila por um minuto. O tempo é desde a última mudança entre up e down."),
    ("dns_statistics.tab_cache", "## Cache\nO cache de respostas compartilhado pelo roteador e pela LAN: entradas, bytes usados contra o `cache-size`, despejos, expiradas, respostas vencidas servidas (RFC 8767) e os tipos guardados e perguntados."),
    ("dns_statistics.tab_clients", "## Clientes\nOs clientes agora: consultas por segundo, quantas respostas foram NXDOMAIN, quantas passaram do limite por cliente, quando perguntaram por último. Só na memória e sem os nomes perguntados (LGPD, Marco Civil art. 14): dá para achar um aparelho em laço ou uma máquina infectada, não para saber o que alguém procura."),
    ("dns_statistics.tab_names", "## Nomes\nOs nomes mais perguntados e os domínios cujos nomes falham (NXDOMAIN, SERVFAIL), de todos os clientes juntos. Um ataque de subdomínio aleatório (todo nome novo, toda resposta NXDOMAIN ou SERVFAIL) aparece como um domínio com milhares de nomes diferentes; o aviso embaixo das tabelas diz isso."),
    ("dns_statistics.tab_overview", "## Visão geral\nO resumo do encaminhador DNS da LAN: os cartões do que importa agora, o gráfico do período, quem respondeu, os códigos de resposta, o transporte e os avisos."),
    ("dns_statistics.tab_upstreams", "## Servidores\nOs servidores de cima (upstream) que o resolvedor consulta: como cada um é perguntado (UDP, DoT, DoH), respostas por segundo, tempo de ida e volta, timeouts, SERVFAIL, respostas truncadas e o estado (up, slow, down). Abaixo, o tempo de ida e volta por faixa."),
    ("dns_statistics.tc_tcp", "## Truncadas\nRespostas UDP dele que vieram truncadas e foram perguntadas de novo em TCP (RFC 7766 §5)."),
    ("dns_statistics.tcp4", "## TCP IPv4\nConsultas em TCP de clientes IPv4 (respostas grandes, DNSSEC, ou depois de um TC)."),
    ("dns_statistics.tcp6", "## TCP IPv6\nConsultas em TCP de clientes IPv6."),
    ("dns_statistics.timeouts", "## Timeout %\nDas vezes que ele foi perguntado desde o reset, quantas ficaram sem resposta dentro do `query-server-timeout`. Cada timeout segura uma vaga de consulta simultânea e atrasa o cliente."),
    ("dns_statistics.transport", "## Transporte\nPor onde as consultas chegaram: UDP ou TCP, IPv4 ou IPv6; as respostas truncadas (TC) e os descartes do kernel no socket UDP."),
    ("dns_statistics.truncated", "## Truncadas (TC)\nRespostas grandes demais para o UDP do cliente: saem sem registros e com o bit TC, e o cliente pergunta de novo em TCP (RFC 1035 §4.2.1, RFC 6891)."),
    ("dns_statistics.types_asked", "## Perguntadas por tipo\nAs consultas desde o reset por tipo de registro pedido."),
    ("dns_statistics.types_cached", "## No cache por tipo\nAs entradas do cache por tipo de registro (A, AAAA, HTTPS…)."),
    ("dns_statistics.udp4", "## UDP IPv4\nConsultas em UDP de clientes IPv4."),
    ("dns_statistics.udp6", "## UDP IPv6\nConsultas em UDP de clientes IPv6."),
    ("dns_statistics.upstream_servfail", "## SERVFAIL %\nDas perguntas a ele, quantas voltaram com SERVFAIL (a próxima vai a outro servidor)."),
    ("dns_statistics.via", "## Via\nComo ele foi perguntado da última vez: UDP (TCP quando a resposta vem truncada), DOT (DNS over TLS, RFC 7858) ou DOH (DNS over HTTPS, RFC 8484)."),
    ("dns_statistics.warnings", "## Avisos\nO que o roteador notou no último minuto: servidor de cima fora ou com timeouts, SERVFAIL alto, limite de consultas simultâneas atingido, cache despejando respostas válidas, descartes no socket. Quem decide é o roteador; a janela só mostra."),
];

/// The engine's warnings (`ip.dns.statistics.print`), by key.
pub(super) const TEMPLATES: &[(&str, &str)] = &[
    ("dns_statistics.warn.cache_evicting", "O cache está cheio: {count} respostas ainda válidas foram despejadas no último minuto"),
    ("dns_statistics.warn.limit_reached", "Max Concurrent Queries ({max}) foi atingido: {count} consultas receberam SERVFAIL no último minuto"),
    ("dns_statistics.warn.random_subdomain", "Domínio {domain}: cerca de {names} nomes diferentes falharam ({rate}/s agora): ataque de subdomínio aleatório ou um cliente quebrado"),
    ("dns_statistics.warn.servfail_high", "{percent} % das respostas do último minuto foram SERVFAIL"),
    ("dns_statistics.warn.socket_drops", "O kernel descartou {count} consultas nos sockets UDP no último minuto"),
    ("dns_statistics.warn.upstream_down", "Servidor {server} fora: falhou e é perguntado por último por um minuto"),
    ("dns_statistics.warn.upstream_timeouts", "Servidor {server}: {percent} % das consultas deram timeout no último minuto"),
];
